// Look for any visible toast/notification element
const toasts = [];
for (const el of document.querySelectorAll('*')) {
  const cs = getComputedStyle(el);
  if (cs.display === 'none' || cs.visibility === 'hidden') continue;
  const t = (el.textContent || '').trim();
  const cls = el.className || '';
  if ((cls.toString().includes('toast') || cls.toString().includes('notif') || cls.toString().includes('snack') || cls.toString().includes('alert') || cls.toString().includes('message')) && t.length > 0 && t.length < 200) {
    const r = el.getBoundingClientRect();
    if (r.width > 0 && r.height > 0) toasts.push({cls: cls.toString().slice(0,50), text: t.slice(0,150), x: Math.round(r.x), y: Math.round(r.y)});
  }
}
return JSON.stringify(toasts, null, 2);

// Search story passage source for any toast/notify gating macro
const ps = Array.from(Story.passages.values());
const matches = [];
for (const p of ps) {
  const src = p.text || '';
  if (/wear school clothes|school clothes to go/i.test(src)) {
    matches.push({name: p.name, snippet: src.match(/.{0,120}wear school clothes.{0,120}|.{0,120}school clothes to go.{0,120}/i)[0]});
  }
}
return JSON.stringify(matches.slice(0,5), null, 2);

