  const txt = (el.textContent || el.getAttribute('alt') || '').trim().slice(0, 40);
  const oc = el.getAttribute('onclick') || el.getAttribute('data-passage') || el.getAttribute('href') || '';
  out.push({tag: el.tagName.toLowerCase(), t: txt, x: Math.round(r.x + r.width/2), y: Math.round(r.y + r.height/2), w: Math.round(r.width), action: oc.slice(0,80)});
}
